// Command attrgen generates the attribute builders shared by package html and
// package html/shorthand from the single table in html/internal/attrtable.
//
// Run it from the repository root:
//
//	go run ./html/internal/attrgen
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"

	"github.com/monstercameron/GoWebComponents/v7/html/internal/attrtable"
)

const generatedHeader = "// Code generated by html/internal/attrgen from html/internal/attrtable; DO NOT EDIT.\n\n"

// main writes the four generated files, one builder file and one case file per package.
func main() {
	parseRoot := "."
	if len(os.Args) > 1 {
		parseRoot = os.Args[1]
	}
	parseOutputs := map[string][]byte{
		filepath.Join(parseRoot, "html", "attrs_gen.go"):                    renderHTMLBuilders(),
		filepath.Join(parseRoot, "html", "attrs_gen_test.go"):               renderCases("html"),
		filepath.Join(parseRoot, "html", "shorthand", "attrs_gen.go"):       renderShorthandBuilders(),
		filepath.Join(parseRoot, "html", "shorthand", "attrs_gen_test.go"): renderCases("shorthand"),
	}
	for parsePath, parseSource := range parseOutputs {
		parseFormatted, parseErr := format.Source(parseSource)
		if parseErr != nil {
			fmt.Fprintf(os.Stderr, "attrgen: format %s: %v\n", parsePath, parseErr)
			os.Exit(1)
		}
		if parseErr = os.WriteFile(parsePath, parseFormatted, 0o644); parseErr != nil {
			fmt.Fprintf(os.Stderr, "attrgen: write %s: %v\n", parsePath, parseErr)
			os.Exit(1)
		}
	}
}

// isBoolKind reports whether the builder takes a bool argument.
func isBoolKind(parseKind attrtable.Kind) bool {
	return parseKind == attrtable.KindEnumBool || parseKind == attrtable.KindAriaBool
}

// renderHTMLBuilders renders attrs_gen.go for package html.
func renderHTMLBuilders() []byte {
	var parseOut bytes.Buffer
	parseOut.WriteString(generatedHeader)
	parseOut.WriteString("package html\n\n")
	for _, parseEntry := range attrtable.Entries {
		fmt.Fprintf(&parseOut, "// %s %s\n", parseEntry.Name, parseEntry.Doc)
		switch parseEntry.Kind {
		case attrtable.KindString:
			fmt.Fprintf(&parseOut, "func %s(parseValue string) PropOption { return Attr(%q, parseValue) }\n\n", parseEntry.Name, parseEntry.Attr)
		case attrtable.KindEnumBool:
			fmt.Fprintf(&parseOut, "func %s(isParseEnabled bool) PropOption { return Attr(%q, formatBoolAttr(isParseEnabled)) }\n\n", parseEntry.Name, parseEntry.Attr)
		case attrtable.KindFlag:
			fmt.Fprintf(&parseOut, "func %s(parseValues ...bool) PropOption {\n\tisParseEnabled := true\n\tif len(parseValues) > 0 {\n\t\tisParseEnabled = parseValues[0]\n\t}\n\treturn Attr(%q, isParseEnabled)\n}\n\n", parseEntry.Name, parseEntry.Attr)
		case attrtable.KindAriaString:
			fmt.Fprintf(&parseOut, "func %s(parseValue string) PropOption { return Aria(%q, parseValue) }\n\n", parseEntry.Name, parseEntry.Attr[len("aria-"):])
		case attrtable.KindAriaBool:
			fmt.Fprintf(&parseOut, "func %s(isParseEnabled bool) PropOption { return Aria(%q, formatBoolAttr(isParseEnabled)) }\n\n", parseEntry.Name, parseEntry.Attr[len("aria-"):])
		case attrtable.KindField:
			fmt.Fprintf(&parseOut, "func %s(parseValue string) PropOption {\n\treturn optionFunc(func(parseProps *Props) { parseProps.%s = parseValue })\n}\n\n", parseEntry.Name, parseEntry.Field)
		}
	}
	return parseOut.Bytes()
}

// renderShorthandBuilders renders attrs_gen.go for package html/shorthand.
func renderShorthandBuilders() []byte {
	var parseOut bytes.Buffer
	parseOut.WriteString(generatedHeader)
	parseOut.WriteString("package shorthand\n\nimport \"github.com/monstercameron/GoWebComponents/v7/html\"\n\n")
	for _, parseEntry := range attrtable.Entries {
		fmt.Fprintf(&parseOut, "// %s delegates to [html.%s].\n", parseEntry.Name, parseEntry.Name)
		switch {
		case parseEntry.Kind == attrtable.KindFlag:
			fmt.Fprintf(&parseOut, "func %s(parseValues ...bool) PropOption { return html.%s(parseValues...) }\n\n", parseEntry.Name, parseEntry.Name)
		case isBoolKind(parseEntry.Kind):
			fmt.Fprintf(&parseOut, "func %s(isParseEnabled bool) PropOption { return html.%s(isParseEnabled) }\n\n", parseEntry.Name, parseEntry.Name)
		default:
			fmt.Fprintf(&parseOut, "func %s(parseValue string) PropOption { return html.%s(parseValue) }\n\n", parseEntry.Name, parseEntry.Name)
		}
	}
	return parseOut.Bytes()
}

// renderCases renders the generated test file that maps each builder name to a
// sample option built through the package's own builder. Compiling it proves
// that both packages expose every table entry.
func renderCases(parsePackage string) []byte {
	var parseOut bytes.Buffer
	parseOut.WriteString(generatedHeader)
	fmt.Fprintf(&parseOut, "package %s\n\n", parsePackage)
	parseOut.WriteString("// getGeneratedAttrCases maps each generated builder name to a sample option\n// built with the string \"sample\" or the bool true.\nfunc getGeneratedAttrCases() map[string]PropOption {\n\treturn map[string]PropOption{\n")
	for _, parseEntry := range attrtable.Entries {
		parseArg := `"sample"`
		if isBoolKind(parseEntry.Kind) || parseEntry.Kind == attrtable.KindFlag {
			parseArg = "true"
		}
		fmt.Fprintf(&parseOut, "\t\t%q: %s(%s),\n", parseEntry.Name, parseEntry.Name, parseArg)
	}
	parseOut.WriteString("\t}\n}\n")
	return parseOut.Bytes()
}
